"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    if ":" in name:
        step_name, arg_str = name.split(":", 1)
        if step_name == "truncate":
            if not arg_str:
                raise ValueError("truncate requires a length argument")
            try:
                length = int(arg_str)
            except ValueError:
                raise ValueError(
                    f"truncate length must be an integer, got {arg_str!r}"
                )
            return Truncate(length)
        # known step with unexpected argument
        if step_name not in STEPS:
            raise KeyError(f"no step named {step_name!r}. Known: {', '.join(sorted(STEPS))}")
        raise KeyError(
            f"step {step_name!r} does not take arguments (got {arg_str!r})"
        )
    if name not in STEPS:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    return STEPS[name]

